class Component extends DCLogic {
  state = { i: null, shown: 0 };
  componentDidMount() { document.documentElement.lang = 'en-US'; this.syncHead(); }
  componentDidUpdate() { this.syncHead(); }
  componentWillUnmount() { document.body.style.overflow = ''; }

  route() {
    const D = window.AHV_PHOTO_COLLECTIONS;
    if (!D) return null;
    const want = this.props.route || '/property-gallery/';
    return D.routes.find(r => r.path === want) || D.routes[0];
  }
  syncHead() {
    const R = this.route(); if (!R || this._head === R.path) return;
    this._head = R.path;
    if (this.state.shown) this.setState({ shown: 0 });
    document.title = R.head.title;
    const set = (sel, attr, val) => { const el = document.head.querySelector(sel); if (el) el.setAttribute(attr, val); };
    set('meta[name="description"]', 'content', R.head.description);
    set('link[rel="canonical"]', 'href', R.head.canonical);
    set('meta[name="robots"]', 'content', R.head.robots);
  }
  open(i) {
    this._from = i;
    this.setState({ i });
    document.body.style.overflow = 'hidden';
    setTimeout(() => { const c = document.getElementById('photo-close'); if (c) c.focus(); }, 30);
  }
  close() {
    const from = this._from;
    this.setState({ i: null });
    document.body.style.overflow = '';
    setTimeout(() => {
      const b = document.querySelector('button[data-photo-index="' + from + '"]') || document.getElementById('show-more');
      if (b) b.focus();
    }, 30);
  }
  go(d) {
    const R = this.route(); if (!R || this.state.i == null) return;
    const n = R.photos.length;
    this.setState(s => ({ i: (s.i + d + n) % n }));
  }
  renderVals() {
    const R = this.route();
    const guard = () => {}; /* preview-only nav guard neutralised for the published site */
    if (!R) return { guard, photos: [], crumbs: [], captionLines: [] };
    const A = 'https://ayurvedichealingvillage.com';
    const batch = this.props.batchSize ?? 12;
    const total = R.photos.length;
    const shown = Math.min(this.state.shown || batch, total);
    const remaining = total - shown;
    const open = this.state.i != null;
    const cur = open ? R.photos[this.state.i] : null;

    return {
      guard,
      crumbs: R.crumbs.slice(0, -1).map(c => ({ label: c.label, url: A + c.path })),
      crumbLast: R.crumbs[R.crumbs.length - 1].label,
      h1: R.h1, intro: R.intro.text, draftDisplay: R.intro.source ? 'none' : 'block',
      tally: shown < total ? ('Showing ' + shown + ' of ' + total + ' photographs')
                           : (total + (total === 1 ? ' photograph' : ' photographs')),
      heroEl: React.createElement('img', { src: R.hero.src, alt: R.hero.alt || '', width: R.hero.w, height: R.hero.h,
        style: { width: '100%', height: 'auto', display: 'block' } }),
      photos: R.photos.slice(0, shown).map((p, i) => ({
        i, name: p.name, ordinal: (i + 1) + ' / ' + total,
        imgEl: React.createElement('img', { src: p.src, alt: p.alt || '', width: p.w, height: p.h,
          loading: i < 2 ? 'eager' : 'lazy', decoding: 'async',
          style: { width: '100%', height: 'auto', display: 'block' } }),
        caption: p.caption || '', capDisplay: p.caption ? 'block' : 'none',
        open: () => this.open(i)
      })),
      moreDisplay: remaining > 0 ? 'block' : 'none',
      moreLabel: 'Show ' + Math.min(batch, remaining) + ' more',
      showMore: () => this.setState(s => ({ shown: Math.min((s.shown || batch) + batch, total) })),
      hasCaptionsBlock: !!R.captionsBlock,
      captionsHeading: R.captionsBlock ? (R.captionsBlock.heading || 'Notes') : '',
      captionLines: R.captionsBlock ? R.captionsBlock.items.map((t, i) => ({ text: t, i })) : [],
      dlgOpen: open, dlgDisplay: open ? 'flex' : 'none',
      dlgLabel: R.h1 + ' — enlarged photograph',
      counter: open ? (this.state.i + 1) + ' of ' + total : '',
      curCaption: cur && cur.caption ? cur.caption : '',
      curCapDisplay: cur && cur.caption ? 'block' : 'none',
      expandedEl: cur ? React.createElement('img', { src: cur.src, alt: cur.alt || '', width: cur.w, height: cur.h,
        style: { display: 'block', maxWidth: '100%', maxHeight: '100%', width: 'auto', height: 'auto', objectFit: 'contain', borderRadius: '4px', background: '#000' } }) : null,
      close: () => this.close(), prev: () => this.go(-1), next: () => this.go(1),
      dlgKey: (e) => {
        if (e.key === 'Escape') { e.preventDefault(); this.close(); return; }
        if (e.key === 'ArrowLeft') { e.preventDefault(); this.go(-1); return; }
        if (e.key === 'ArrowRight') { e.preventDefault(); this.go(1); return; }
        if (e.key === 'Tab') {
          const f = [...e.currentTarget.querySelectorAll('button')];
          const first = f[0], last = f[f.length - 1];
          if (e.shiftKey && document.activeElement === first) { e.preventDefault(); last.focus(); }
          else if (!e.shiftKey && document.activeElement === last) { e.preventDefault(); first.focus(); }
        }
      }
    };
  }
}
